        var ledgerError = '';
        try { recordLedgerUsage(payload.totalBalance, payload.currency, payload.accountTag, Date.parse(payload.updatedAt)); } catch (err) { ledgerError = String((err && err.message) || err).slice(0, 160); }
        var visible;
        try { visible = publicBalance(payload); } catch (err) { throw err; }
